  --accent-color: #007bff;
  --text-color: #1a1a1a;
  --muted-text: #666666;
  --bg-color: #f8f9fa;
  --border-color: #e0e0e0;
  --card-bg: #ffffff;
  --transition: all 0.3s ease;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  line-height: 1.6;
  color: var(--text-color);
  background-color: var(--bg-color);
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  border: 0;
}

.sr-only-focusable:focus {
  position: static;
  width: auto;
  height: auto;
  clip: auto;
  overflow: visible;
  padding: 1rem;
  background: var(--primary-color);
  color: var(--secondary-color);
  z-index: 1000;
}

/* Layout */
header {
  background: var(--secondary-color);
  border-bottom: 1px solid var(--border-color);
  padding: 1rem 2rem;
  position: sticky;
  top: 0;
  z-index: 100;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.logo {
  font-size: 1.5rem;
  font-weight: 800;
  text-decoration: none;
  color: var(--primary-color);
}

nav ul {
  display: flex;
  list-style: none;
  gap: 2rem;
}

nav a {
  text-decoration: none;
  color: var(--text-color);
  font-weight: 500;
  transition: var(--transition);
}

nav a:hover, nav a:focus {
  color: var(--accent-color);
  outline: 2px solid var(--accent-color);
  outline-offset: 4px;
}

main {
  max-width: 1200px;
  margin: 0 auto;
  padding: 2rem;
}

/* Hero */
.hero {
  background: var(--primary-color);
  color: var(--secondary-color);
  padding: 4rem 2rem;
  text-align: center;
  border-radius: 8px;
  margin-bottom: 3rem;
}

.hero h1 {
  font-size: 3rem;
  margin-bottom: 1rem;
}

.hero p {
  font-size: 1.25rem;
  margin-bottom: 2rem;
  opacity: 0.9;
}

.cta-button {
  display: inline-block;
  background: var(--secondary-color);
  color: var(--primary-color);
  padding: 0.75rem 2rem;
  text-decoration: none;
  font-weight: 600;
  border-radius: 4px;
  transition: var(--transition);
}

.cta-button:hover, .cta-button:focus {
  background: var(--accent-color);
  color: var(--secondary-color);
}

/* Sections */
section {
  margin-bottom: 4rem;
}

section h2 {
  font-size: 2rem;
  margin-bottom: 2rem;
  border-bottom: 2px solid var(--primary-color);
  padding-bottom: 0.5rem;
  display: inline-block;
}

.grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 2rem;
}

/* Product Card */
.product-card {
  background: var(--card-bg);
  border: 1px solid var(--border-color);
  border-radius: 8px;
  overflow: hidden;
  transition: var(--transition);
  display: flex;
  flex-direction: column;
}

.product-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 10px 20px rgba(0,0,0,0.1);
}

.product-image {
  width: 100%;
  aspect-ratio: 1;
  background: #eee;
  object-fit: cover;
}

.product-info {
  padding: 1.5rem;
  flex-grow: 1;
  display: flex;
  flex-direction: column;
}

.product-info h3 {
  margin-bottom: 0.5rem;
}

.product-info h3 a {
  text-decoration: none;
  color: var(--text-color);
}

.product-info h3 a:hover, .product-info h3 a:focus {
  color: var(--accent-color);
}

.price {
  font-weight: 700;
  font-size: 1.25rem;
  margin-bottom: 1rem;
}

.deal-price {
  color: #d9534f;
}

.original-price {
  text-decoration: line-through;
  color: var(--muted-text);
  font-size: 1rem;
  margin-right: 0.5rem;
}

.add-to-cart {
  margin-top: auto;
  background: var(--primary-color);
  color: var(--secondary-color);
  border: none;
  padding: 0.75rem;
  border-radius: 4px;
  cursor: pointer;
  font-weight: 600;
  transition: var(--transition);
}

.add-to-cart:hover, .add-to-cart:focus {
  background: var(--accent-color);
}

/* Editorial */
.editorial-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(400px, 1fr));
  gap: 2rem;
}

.editorial-card {
  position: relative;
  border-radius: 8px;
  overflow: hidden;
  min-height: 300px;
  display: flex;
  align-items: flex-end;
  color: var(--secondary-color);
  background: #333;
}

.editorial-card img {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  opacity: 0.6;
}

.editorial-content {
  position: relative;
  padding: 2rem;
  z-index: 1;
}

/* Footer */
footer {
  background: var(--primary-color);
  color: var(--secondary-color);
  padding: 4rem 2rem;
  margin-top: 4rem;
}

.footer-grid {
  max-width: 1200px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 3rem;
}

.footer-section h4 {
  margin-bottom: 1.5rem;
  text-transform: uppercase;
  letter-spacing: 1px;
}

.footer-section ul {
  list-style: none;
}

.footer-section ul li {
  margin-bottom: 0.5rem;
}

.footer-section a {
  color: #ccc;
  text-decoration: none;
  transition: var(--transition);
}

.footer-section a:hover, .footer-section a:focus {
  color: var(--secondary-color);
}

@media (max-width: 768px) {
  header {
    flex-direction: column;
    gap: 1rem;
  }

  .hero h1 {
    font-size: 2rem;
  }

  .editorial-grid {
    grid-template-columns: 1fr;
  }
}

@media (prefers-reduced-motion: reduce) {
  * {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}
